package me.neobliz1.ecomonitoring.platform.history.infrastructure.adapter.inbound.grpc;import static me.neobliz1.ecomonitoring.platform.history.domain.model.constant.HistoricalCacheConstants.BUCKETS_REGION;import static me.neobliz1.ecomonitoring.platform.history.domain.model.constant.HistoricalCacheConstants.QUERIES_REGION;import io.github.neobliz1.validproto.annotation.ValidProto;import io.github.neobliz1.validproto.annotation.ValidatedProto;import io.grpc.Status;import io.grpc.StatusRuntimeException;import io.grpc.stub.StreamObserver;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import me.neobliz1.ecomonitoring.platform.history.domain.model.dto.WeatherMapBucketCacheDto;import me.neobliz1.ecomonitoring.platform.history.domain.model.entity.WeatherGridCellMetric;import me.neobliz1.ecomonitoring.platform.history.domain.model.entity.WeatherMapBucket;import me.neobliz1.ecomonitoring.platform.history.domain.port.inbound.HistoricalDataConvertService;import me.neobliz1.ecomonitoring.platform.history.domain.port.outbound.HistoricalQueryRepository;import me.neobliz1.ecomonitoring.platform.history.infrastructure.adapter.inbound.grpc.record.SpatialQueryKey;import me.neobliz1.ecomonitoring.platform.model.exception.L1CacheNotAvailableException;import me.neobliz1.ecomonitoring.platform.shared.contracts.proto.map.GridCellLayers;import me.neobliz1.ecomonitoring.platform.shared.contracts.proto.map.WeatherMap;import org.jspecify.annotations.NonNull;import org.springframework.cache.Cache;import org.springframework.cache.CacheManager;import weather.history.HistoryServiceGrpc;import weather.history.SpatialBoxRequest;import java.util.List;import java.util.Map;import java.util.Optional;import java.util.UUID;import java.util.stream.Collectors;@Slf4j@ValidatedProto@RequiredArgsConstructorpublic class HistoricalExternalCommunicationObserver extends HistoryServiceGrpc.HistoryServiceImplBase {    private final HistoricalQueryRepository historicalQueryRepository;    private final HistoricalDataConvertService weatherMapConverter;    private final CacheManager springL1CacheManager;    @Override    public void findFilteredGridDataBySpatialBox(@ValidProto SpatialBoxRequest request, StreamObserver<WeatherMap> responseObserver) {        long timestampBucketInMillis = request.getTimestampBucket();        double minLat = request.getMinLat();        double maxLat = request.getMaxLat();        double minLon = request.getMinLon();        double maxLon = request.getMaxLon();        int timeIntervalInMinutes = request.getTimeIntervalInMinutes();        if(log.isDebugEnabled()) {            log.debug("GRPC request: {} [{}#{}#{}#{}] has been received and is processing.",                    timestampBucketInMillis, minLat, maxLat, minLon, maxLon);        }        try {            SpatialQueryKey queryKey = new SpatialQueryKey(timestampBucketInMillis, timeIntervalInMinutes, minLat, maxLat, minLon, maxLon);            Cache grpcQueryCache = springL1CacheManager.getCache(QUERIES_REGION);            if(grpcQueryCache==null) {                throw new L1CacheNotAvailableException(QUERIES_REGION);            }            WeatherMap cachedResponse = grpcQueryCache.get(queryKey, WeatherMap.class);            if(cachedResponse!=null) {                if(log.isDebugEnabled()) {                    log.debug("Mux Performance Hit! Serving complete WeatherMap Protobuf array directly from shared L1 cache memory.");                }                responseObserver.onNext(cachedResponse);                responseObserver.onCompleted();                return;            }            List<WeatherGridCellMetric> weatherGridCells = getWeatherGridCellMetrics(timestampBucketInMillis, timeIntervalInMinutes,                    minLat, maxLat, minLon, maxLon);            if(weatherGridCells.isEmpty()) {                throw Status.NOT_FOUND                        .withDescription("No grid metrics found within the requested time or any past historical buckets.")                        .asRuntimeException();            }            Map<String, GridCellLayers> cellLayersMap = weatherGridCells.stream()                    .collect(Collectors.toMap(                            WeatherGridCellMetric::getGeohash,                            weatherMapConverter::convertWeatherGridCellsToWeatherMap,                            (existing, replacement) -> existing                    ));            WeatherMap weatherMap = WeatherMap.newBuilder()                    .setIntervalMinutes(timeIntervalInMinutes)                    .setTimestampBucket(timestampBucketInMillis)                    .putAllGridCells(cellLayersMap)                    .build();            grpcQueryCache.put(queryKey, weatherMap);            responseObserver.onNext(weatherMap);            responseObserver.onCompleted();        } catch(StatusRuntimeException e) {            log.warn("Spatial box lookup failed with explicit status: {}", e.getStatus());            responseObserver.onError(e);        } catch(Exception e) {            log.error("Unexpected error processing spatial box request", e);            responseObserver.onError(Status.INTERNAL                    .withDescription("An unexpected internal error occurred processing data.")                    .withCause(e)                    .asRuntimeException());        }    }    private @NonNull List<WeatherGridCellMetric> getWeatherGridCellMetrics(long timestampBucketInMillis, int timeIntervalInMinutes, double minLat, double maxLat, double minLon, double maxLon) {        UUID bucketId = resolveBucketIdWithCache(timestampBucketInMillis, timeIntervalInMinutes);        List<WeatherGridCellMetric> weatherGridCells = List.of();        if(bucketId!=null) {            weatherGridCells = historicalQueryRepository                    .findByBucketIdAndSpatialBox(bucketId, minLat, maxLat, minLon, maxLon);        }        long searchTimestamp = timestampBucketInMillis;        while(weatherGridCells.isEmpty()) {            log.info("No cells found. Searching for the next bucket timestamp: {}", searchTimestamp);            Optional<WeatherMapBucket> pastBucketOpt = historicalQueryRepository                    .findClosestPastBucket(searchTimestamp, timeIntervalInMinutes);            if(pastBucketOpt.isEmpty()) {                log.warn("Exhausted all historical buckets. No data found.");                break;            }            WeatherMapBucket pastBucket = pastBucketOpt.get();            UUID pastBucketId = pastBucket.getId();            log.info("Evaluating past bucket ID: {} from timestamp: {}", pastBucketId, pastBucket.getTimestampBucket());            weatherGridCells = historicalQueryRepository                    .findByBucketIdAndSpatialBox(pastBucketId, minLat, maxLat, minLon, maxLon);            searchTimestamp = pastBucket.getTimestampBucket();        }        return weatherGridCells;    }    private UUID resolveBucketIdWithCache(long timestampBucketInMillis, int timeIntervalInMinutes) {        UUID deterministicId = UUID.nameUUIDFromBytes((String.valueOf(timestampBucketInMillis)+timeIntervalInMinutes).getBytes());        Cache bucketL1Cache = springL1CacheManager.getCache(BUCKETS_REGION);        if(bucketL1Cache==null) {            throw new L1CacheNotAvailableException(BUCKETS_REGION);        }        WeatherMapBucketCacheDto cachedBucket = bucketL1Cache.get(deterministicId, WeatherMapBucketCacheDto.class);        if(cachedBucket!=null) {            return cachedBucket.id();        }        Optional<WeatherMapBucket> optionalWeatherMapBucket = historicalQueryRepository                .findByTimestampBucketAndIntervalMinutes(timestampBucketInMillis, timeIntervalInMinutes);        if(optionalWeatherMapBucket.isEmpty()) {            return null;        }        WeatherMapBucket weatherMapBucket = optionalWeatherMapBucket.get();        UUID bucketId = weatherMapBucket.getId();        WeatherMapBucketCacheDto dtoToCache = new WeatherMapBucketCacheDto(                bucketId,                weatherMapBucket.getTimestampBucket(),                weatherMapBucket.getIntervalMinutes(),                weatherMapBucket.getVersion()        );        bucketL1Cache.put(deterministicId, dtoToCache);        return bucketId;    }}